/**
 * GENERATED from the players' screenshots of the game (SPT 4.1.6, 1920×1080) in German, Japanese, Chinese, Polish, Spanish,
 * Brazilian Portuguese, French, Korean and Turkish — do not edit by hand. Real Tesseract output (tesseract.js, tessdata_fast,
 * each language's model + English) as the app reads each screen: the quest scanner's whole-screen pass (page mode 6; Japanese
 * and Chinese rebuilt from the word boxes) of the Tasks table, the traders' screen and a trader's Tasks tab (the Collector at
 * Fence) with the word boxes of the band of the portraits and the standing; the exit lists (top-right corner, dark on white,
 * ×2); the item cards' lines (TOOLTIP_OCR_PARAMETERS); the flea's chips and rows; the stash labels (sparse text). With the
 * game's names (tarkov.dev's dictionaries) of the quests, items and exits they show. The profile's nickname is «TESTPILOT»;
 * no money, no other player's name. The screenshots themselves are not kept here.
 */
export interface ScreenWord { text: string; bbox: { x0: number; y0: number; x1: number; y1: number } }
export interface LanguageScreens {
  tasks: { text: string }
  traders: { text: string; blocks: ScreenWord[][][] }
  collector: { text: string; blocks: ScreenWord[][][] }
  exits: { customs: string; woods: string }
  /** Each card found around the cursor: its lines' readings. */
  tooltips: string[][][]
  flea: { chips: string[]; rows: Array<{ seller: string; info: string; name: string }> }
  labels: { stash: string[]; collector: string[] }
  /** The game's names in this language: quests by id, items by id, exits by the maps' keys. */
  names: { quests: Record<string, string>; items: Record<string, { name: string; shortName: string }>; exits: Record<string, string> }
}

